80	@RequestMapping("/api")
81	public class OwnerRestControllerV1 implements OwnersApi {
82	
83	    /**
84	     * Dedicated audit logger. On a successful owner create an audit line carrying the owner id,
85	     * the {@code memberId} and the {@code registrationDate} is emitted to this named logger.
86	     */
87	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
88	
89	    /**
90	     * Dedicated notification logger. On a successful owner create a welcome-notification line
91	     * carrying the owner id and the {@code memberId} is enqueued by emitting it to this named logger.
92	     */
93	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
94	
95	    /**
96	     * Monotonically increasing sequence number stamped onto every {@code OWNER_CREATED} structured
97	     * event, so events can be totally ordered across creates. Shared across all creates for the life
98	     * of the application; a plain counter is enough since it only ever grows.
99	     */
100	    private static final AtomicLong OWNER_EVENT_SEQ = new AtomicLong();
101	
102	    /**
103	     * Serializes the immutable {@code OWNER_CREATED} structured event to its canonical JSON form.
104	     */
105	    private static final ObjectMapper EVENT_MAPPER = JsonMapper.builder().build();
