166	    /**
167	     * Rejects an owner payload that is missing or blank in any of the required fields
168	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
169	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
170	     * value as present; this guard closes that gap so a blank in any required field is
171	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
172	     * the name of each offending field.
173	     */
174	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
175	        List<String> missing = new ArrayList<>();
176	        if (isBlank(ownerFieldsDto.getFirstName())) {
177	            missing.add("firstName");
178	        }
179	        if (isBlank(ownerFieldsDto.getLastName())) {
180	            missing.add("lastName");
181	        }
182	        if (isBlank(normalizedAddress)) {
183	            missing.add("address");
184	        }
185	        if (isBlank(ownerFieldsDto.getCity())) {
186	            missing.add("city");
187	        }
188	        if (isBlank(ownerFieldsDto.getTelephone())) {
189	            missing.add("telephone");
190	        }
191	        if (!missing.isEmpty()) {
192	            throw new MissingOwnerFieldsException(missing);
193	        }
194	    }
195	
196	    private static boolean isBlank(String value) {
197	        return value == null || value.isBlank();
198	    }
199	
200	    /**
201	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
202	     */
203	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
204	
205	    /**
206	     * Required national-number length per country calling code. When the normalized E.164 number
207	     * begins with one of these codes, the digits that follow must number exactly the mapped value:
208	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Codes absent from
209	     * this map carry no per-country length rule beyond the generic E.164 8-to-15-digit bound.
210	     */
211	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
212	        "+61", 9,
213	        "+1", 10);
214	
215	    /**
216	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
217	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
218	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
219	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
220	     * stored as '+61412345678'. When the country code has a known national-number length ('+61'
221	     * requires 9 national digits, '+1' requires 10) the national digits must match it exactly. A
222	     * value that cannot form a valid E.164 number, or whose national length is wrong for its
223	     * country, is rejected via {@link InvalidTelephoneException}, which the exception handler
224	     * translates to a 400.
225	     */
226	    private static String normalizeTelephone(String telephone) {
227	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
228	        String e164;
229	        if (cleaned.startsWith("+")) {
230	            e164 = cleaned;
231	        } else {
232	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
233	            e164 = "+61" + national;
234	        }
235	        if (!E164_PATTERN.matcher(e164).matches()) {
236	            throw new InvalidTelephoneException(telephone);
237	        }
238	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
239	            String code = rule.getKey();
240	            if (e164.startsWith(code)) {
241	                int nationalLength = e164.length() - code.length();
242	                if (nationalLength != rule.getValue()) {
243	                    throw new InvalidTelephoneException(telephone);
244	                }
245	                break;
246	            }
247	        }
248	        return e164;
249	    }
250	
251	    /**
252	     * Matches a well-formed postcode: exactly four digits.
253	     */
254	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("\\d{4}");
255	
256	    /**
257	     * The canonical region for each city that has one. A city absent from this table has no known
258	     * region and so accepts any 4-digit postcode. This is the same fixed city-to-region table used
259	     * to derive an owner's locality.
260	     */
261	    private static final Map<String, String> CITY_REGION = Map.of(
262	        "Sydney", "NSW",
263	        "Melbourne", "VIC",
264	        "Brisbane", "QLD");
265	
266	    /**
267	     * The inclusive 4-digit postcode range for each region, as {@code {low, high}}: NSW 2000-2099,
268	     * VIC 3000-3099, QLD 4000-4099.
269	     */
270	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
271	        "NSW", new int[] {2000, 2099},
272	        "VIC", new int[] {3000, 3099},
273	        "QLD", new int[] {4000, 4099});
274	
275	    /**
276	     * Validates an owner's optional postcode. A {@code null} postcode is left as-is (the field is
277	     * optional). When present it must be exactly four digits; and when the owner's city maps to a
278	     * known region it must fall within that region's inclusive postcode range (NSW 2000-2099, VIC
279	     * 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode. An
280	     * invalid or out-of-range value is rejected via {@link InvalidPostcodeException}, which the
281	     * exception handler translates to a 400.
282	     */
283	    private static void validatePostcode(String city, String postcode) {
284	        if (postcode == null) {
285	            return;
286	        }
287	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
288	            throw new InvalidPostcodeException(postcode);
289	        }
290	        String region = CITY_REGION.get(city);
291	        if (region == null) {
292	            return;
293	        }
294	        int[] range = REGION_POSTCODES.get(region);
295	        int value = Integer.parseInt(postcode);
296	        if (value < range[0] || value > range[1]) {
297	            throw new InvalidPostcodeException(postcode);
298	        }
299	    }
300	
301	    /**
302	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
303	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
304	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
305	     */
306	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
307	
308	    /**
309	     * Disposable-email domains that an owner's email may not use. An address whose domain (the part
310	     * after the final {@code @}, compared case-insensitively) is one of these is rejected. Kept as a
311	     * fixed set so the block list is explicit and easy to extend.
312	     */
313	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
314	        "mailinator.com",
315	        "tempmail.com",
316	        "guerrillamail.com");
317	
318	    /**
319	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
320	     * optional). When present it must be a syntactically valid address whose domain is not on the
321	     * disposable-domain block list; a valid value is lower-cased so it is stored and returned in
322	     * canonical form. An invalid or disposable-domain value is rejected via
323	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
324	     */
325	    private static String normalizeEmail(String email) {
326	        if (email == null) {
327	            return null;
328	        }
329	        if (!EMAIL_PATTERN.matcher(email).matches()) {
330	            throw new InvalidEmailException(email);
331	        }
332	        String normalized = email.toLowerCase(Locale.ROOT);
333	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
334	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
335	            throw new InvalidEmailException(email);
336	        }
337	        return normalized;
338	    }
339	
340	    /**
341	     * The single derived identity of an owner: the 64-character lower-case SHA-256 hex digest over
342	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, into which all
343	     * duplicate detection is consolidated. Two owners are the same identity only when this whole key
344	     * matches: because the normalized telephone is part of the pre-image, two owners who share a
345	     * surname (same soundex) and postcode but carry different telephones have different identity
346	     * keys. A {@code null} email contributes an empty middle segment. This is the value returned to
347	     * callers as {@code identityKey}.
348	     */
349	    private static String identityKeyFor(String normalizedTelephone, String normalizedEmail, String lastName) {
350	        String preimage = normalizedTelephone + "|" + (normalizedEmail == null ? "" : normalizedEmail)
351	            + "|" + soundex(lastName);
352	        return sha256Hex(preimage);
353	    }
354	
355	    /**
356	     * The American Soundex code of a name: its first letter followed by up to three digits encoding
357	     * the remaining consonants (b/f/p/v->1, c/g/j/k/q/s/x/z->2, d/t->3, l->4, m/n->5, r->6), with
358	     * adjacent duplicate codes collapsed, vowels (and y) resetting the run, and h/w transparent so
359	     * consonants they separate are still treated as adjacent. The result is padded with zeros to
360	     * exactly four characters. A {@code null} or letterless name yields the empty string.
361	     */
362	    private static String soundex(String name) {
363	        if (name == null) {
364	            return "";
365	        }
366	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
367	        if (letters.isEmpty()) {
368	            return "";
369	        }
370	        StringBuilder code = new StringBuilder();
371	        code.append(letters.charAt(0));
372	        char prev = soundexCode(letters.charAt(0));
373	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
374	            char c = letters.charAt(i);
375	            if (c == 'H' || c == 'W') {
376	                continue;
377	            }
378	            char digit = soundexCode(c);
379	            if (digit != '0' && digit != prev) {
380	                code.append(digit);
381	            }
382	            prev = digit;
383	        }
384	        while (code.length() < 4) {
385	            code.append('0');
386	        }
387	        return code.toString();
388	    }
389	
390	    /**
391	     * The Soundex digit for a single upper-case letter, or {@code '0'} for a vowel, y, h or w (which
392	     * carry no code).
393	     */
394	    private static char soundexCode(char c) {
395	        return switch (c) {
396	            case 'B', 'F', 'P', 'V' -> '1';
397	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
398	            case 'D', 'T' -> '3';
399	            case 'L' -> '4';
400	            case 'M', 'N' -> '5';
401	            case 'R' -> '6';
402	            default -> '0';
403	        };
404	    }
405	
406	    /**
407	     * The full lower-case SHA-256 hex digest (64 characters) of the UTF-8 bytes of {@code value}.
408	     */
409	    private static String sha256Hex(String value) {
410	        try {
411	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
412	            StringBuilder sb = new StringBuilder(digest.length * 2);
413	            for (byte b : digest) {
414	                sb.append(String.format("%02x", b));
415	            }
416	            return sb.toString();
417	        } catch (NoSuchAlgorithmException ex) {
418	            throw new IllegalStateException("SHA-256 not available", ex);
419	        }
420	    }
421	
422	    /**
423	     * Rejects a create whose derived identity collides with an existing owner's, reported via
424	     * {@link DuplicateTelephoneException} which the handler translates to a 409. Duplicate detection
425	     * is now the single identity key: the new owner's {@link #identityKeyFor identityKey} (the
426	     * SHA-256 over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}) is
427	     * compared against each existing owner's, ignoring owners flagged deleted. The email-domain
428	     * block list has already been applied while normalizing the email, so it takes effect first. An
429	     * existing telephone that cannot form a valid E.164 number is skipped rather than colliding.
430	     * Because the telephone is part of the key, two owners with the same surname and postcode but
431	     * different telephones no longer collide here - they are surfaced as a soft match instead. The
432	     * former separate telephone, email and household 409 blocks are all subsumed by this key.
433	     */
434	    private void rejectDuplicateIdentity(String normalizedTelephone, String normalizedEmail, String lastName) {
435	        String identityKey = identityKeyFor(normalizedTelephone, normalizedEmail, lastName);
436	        for (Owner existing : this.clinicService.findAllOwners()) {
437	            if (existing.isDeleted()) {
438	                continue;
439	            }
440	            String existingTelephone;
441	            try {
442	                existingTelephone = normalizeTelephone(existing.getTelephone());
443	            } catch (InvalidTelephoneException ex) {
444	                continue;
445	            }
446	            String existingEmail = existing.getEmail() == null ? null : existing.getEmail().toLowerCase(Locale.ROOT);
447	            String existingKey = identityKeyFor(existingTelephone, existingEmail, existing.getLastName());
448	            if (identityKey.equals(existingKey)) {
449	                throw new DuplicateTelephoneException(normalizedTelephone);
450	            }
451	        }
452	    }
453	
454	    /**
455	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
456	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
457	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
458	     * spacing do not defeat the duplicate-household check.
459	     */
460	    private static String collapse(String value) {
461	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
462	    }
463	
464	    /**
465	     * Normalizes an owner's address into a canonical form applied on every create: leading and
466	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
467	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
468	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
469	     * and returned, and is the form every address comparison (duplicate-household detection and the
470	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
471	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
472	     * so normalizing an already-normalized address is a no-op.
473	     */
474	    private static String normalizeAddress(String address) {
475	        if (address == null) {
476	            return "";
477	        }
478	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
479	        if (collapsed.isEmpty()) {
480	            return "";
481	        }
482	        String[] tokens = collapsed.split(" ");
483	        StringBuilder sb = new StringBuilder(collapsed.length());
484	        for (int i = 0; i < tokens.length; i++) {
485	            String token = tokens[i];
486	            switch (token) {
487	                case "ST" -> token = "STREET";
488	                case "RD" -> token = "ROAD";
489	                case "AVE" -> token = "AVENUE";
490	                default -> {
491	                }
492	            }
493	            if (i > 0) {
494	                sb.append(' ');
495	            }
496	            sb.append(token);
497	        }
498	        return sb.toString();
499	    }
500	
501	    /**
502	     * Derives an owner's region code from its postcode, falling back to its city. A present postcode
503	     * that falls in a known region's inclusive 4-digit range wins (NSW 2000-2099, VIC 3000-3099, QLD
504	     * 4000-4099); otherwise the fixed city-to-region table is consulted (Sydney -> NSW, Melbourne ->
505	     * VIC, Brisbane -> QLD); a value resolved by neither is {@code "UNKNOWN"}. This is the single
506	     * region derivation shared by the {@code memberId} and the owner's locality.
507	     */
508	    private static String deriveRegion(String city, String postcode) {
509	        if (postcode != null) {
510	            try {
511	                int pc = Integer.parseInt(postcode.trim());
512	                for (Map.Entry<String, int[]> range : REGION_POSTCODES.entrySet()) {
513	                    int[] bounds = range.getValue();
514	                    if (pc >= bounds[0] && pc <= bounds[1]) {
515	                        return range.getKey();
516	                    }
517	                }
518	            } catch (NumberFormatException ignored) {
519	                // not a numeric postcode; fall back to the city-to-region table
520	            }
521	        }
522	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
523	    }
524	
525	    /**
526	     * Builds the {@code memberId} for a newly created owner, formatted {@code '<REGION><FY><HASH8><CHK>'}
527	     * where {@code REGION} is the region code derived from the owner's postcode (falling back to its
528	     * city), {@code FY} is the 2-digit fiscal year of the {@code registrationDate} (matching the owner's
529	     * {@code fiscalYear}), {@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
530	     * {@code normalizedTelephone + lastName} (the same HASH8 used by the region-and-hash identity), and
531	     * {@code CHK} is a single Luhn check digit computed over the digits of {@code <REGION><FY><HASH8>}
532	     * (e.g. {@code 'NSW271A2B3C4D5'}). This is a stable identity: it carries no sequence number and
533	     * depends only on the owner's own region, fiscal year, telephone and surname.
534	     */
535	    private static String memberIdFor(String region, LocalDate registrationDate,
536	                                      String normalizedTelephone, String lastName) {
537	        String fy = String.format("%02d", fiscalYearOf(registrationDate) % 100);
538	        String hash8 = sha256HexPrefix(normalizedTelephone + lastName, 8);
539	        String base = region + fy + hash8;
540	        return base + luhnCheckDigit(base);
541	    }
