59	     * the identity's region derivation, where the postcode range takes precedence (NSW 2000-2099, VIC
60	     * 3000-3099, QLD 4000-4099) and the city-to-region table (Sydney->NSW, Melbourne->VIC,
61	     * Brisbane->QLD) is the fallback, otherwise "UNKNOWN". This is the same region embedded as the
62	     * {@code REGION} prefix of the owner's {@code memberId}.
63	     */
64	    default String deriveLocality(Owner owner) {
65	        if (owner == null) {
66	            return null;
67	        }
68	        String postcode = owner.getPostcode();
69	        if (postcode != null) {
70	            try {
71	                int pc = Integer.parseInt(postcode.trim());
72	                if (pc >= 2000 && pc <= 2099) {
73	                    return "NSW";
74	                }
75	                if (pc >= 3000 && pc <= 3099) {
76	                    return "VIC";
77	                }
78	                if (pc >= 4000 && pc <= 4099) {
79	                    return "QLD";
80	                }
81	            }
82	            catch (NumberFormatException ignored) {
83	                // not a numeric postcode; fall back to the city-to-region table
84	            }
85	        }
86	        String city = owner.getCity();
87	        if ("Sydney".equals(city)) {
88	            return "NSW";
89	        }
90	        if ("Melbourne".equals(city)) {
91	            return "VIC";
92	        }
93	        if ("Brisbane".equals(city)) {
94	            return "QLD";
95	        }
96	        return "UNKNOWN";
97	    }
98	
99	    /**
100	     * Derive the owner's marketing segment, formatted {@code '<TIER>_<AREA>'}. TIER is
101	     * {@code "PREMIUM"} when the owner's {@code membershipLevel} is 3 or more, otherwise
102	     * {@code "STANDARD"} (a missing membershipLevel counts as below 3). AREA is {@code "METRO"}
103	     * when the owner's locality is a known region (NSW, VIC or QLD), otherwise {@code "REGIONAL"}.
104	     * Returns null when the owner is absent.
105	     */
106	    default String deriveOwnerSegment(Owner owner) {
107	        if (owner == null) {
108	            return null;
109	        }
110	        Integer membershipLevel = owner.getMembershipLevel();
111	        String tier = (membershipLevel != null && membershipLevel >= 3) ? "PREMIUM" : "STANDARD";
112	        String locality = deriveLocality(owner);
113	        boolean metro = "NSW".equals(locality) || "VIC".equals(locality) || "QLD".equals(locality);
114	        return tier + "_" + (metro ? "METRO" : "REGIONAL");
115	    }
116	
117	    /**
118	     * Disposable-email domains whose subdomains are treated as disposable-adjacent. This is the same
119	     * fixed block list the create endpoint rejects on an exact match; an owner therefore never carries
120	     * an email whose domain is exactly one of these, so only a subdomain of one survives to be flagged.
121	     */
122	    java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
123	        "mailinator.com",
124	        "tempmail.com",
125	        "guerrillamail.com");
126	
127	    /**
128	     * Derive the owner's {@code riskFlag}: true when any of these hold, otherwise false. The owner is
129	     * a possible duplicate ({@code possibleDuplicate} is true); the owner's email domain is
130	     * disposable-adjacent ({@link #isDisposableAdjacent}); or the owner's city is over its soft
131	     * capacity ({@code capacityWarning} is true, i.e. the city already held 40 or more owners when
132	     * this owner was created). Returns false when the owner is absent.
133	     */
134	    default boolean deriveRiskFlag(Owner owner) {
135	        if (owner == null) {
136	            return false;
137	        }
138	        boolean possibleDuplicate = Boolean.TRUE.equals(owner.getPossibleDuplicate());
139	        boolean overSoftCapacity = Boolean.TRUE.equals(owner.getCapacityWarning());
140	        boolean disposableAdjacent = isDisposableAdjacent(owner.getEmail());
141	        return possibleDuplicate || disposableAdjacent || overSoftCapacity;
142	    }
143	
144	    /**
145	     * Whether an email's domain is disposable-adjacent: the domain (the part after the final
146	     * {@code @}, compared case-insensitively) is a proper subdomain of a known disposable-email
147	     * domain, i.e. it ends with {@code '.' + disposableDomain}. An exact match to a disposable domain
148	     * is rejected on create, so it never reaches here. A null or malformed email is not adjacent.
149	     */
150	    default boolean isDisposableAdjacent(String email) {
151	        if (email == null) {
152	            return false;
153	        }
154	        int at = email.lastIndexOf('@');
155	        if (at < 0) {
156	            return false;
157	        }
158	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
159	        for (String disposable : DISPOSABLE_EMAIL_DOMAINS) {
160	            if (domain.endsWith("." + disposable)) {
161	                return true;
162	            }
163	        }
164	        return false;
165	    }
166	
167	    /**
168	     * Derive the owner's IANA timezone from its locality/region using the fixed region-to-timezone
169	     * table (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane). The region is
170	     * the same value reported as {@code locality}. Returns null when the owner is absent or the region
171	     * has no known timezone.
172	     */
173	    default String deriveTimezone(Owner owner) {
174	        if (owner == null) {
175	            return null;
176	        }
177	        String region = deriveLocality(owner);
178	        if ("NSW".equals(region)) {
179	            return "Australia/Sydney";
180	        }
181	        if ("VIC".equals(region)) {
182	            return "Australia/Melbourne";
183	        }
184	        if ("QLD".equals(region)) {
185	            return "Australia/Brisbane";
186	        }
187	        return null;
188	    }
189	
190	    /**
191	     * Derive the owner's age band from its birthDate against the registrationDate: 'MINOR' when
192	     * under 18, 'ADULT' from 18 to 64, and 'SENIOR' at 65 or older. The age is the number of whole
193	     * years between birthDate and registrationDate (falling back to the current date when the owner
194	     * has no registrationDate). Returns null when the owner or its birthDate is absent, so no
195	     * ageBand is reported.
196	     */
197	    default String deriveAgeBand(Owner owner) {
198	        if (owner == null || owner.getBirthDate() == null) {
199	            return null;
200	        }
201	        java.time.LocalDate reference = owner.getRegistrationDate() != null
202	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
203	        int age = java.time.Period.between(owner.getBirthDate(), reference).getYears();
204	        if (age < 18) {
205	            return "MINOR";
206	        }
207	        if (age < 65) {
208	            return "ADULT";
209	        }
210	        return "SENIOR";
211	    }
212	
213	    /**
214	     * Known E.164 country calling codes, longest first, used to split a stored telephone into its
215	     * country code and national digits. A number whose code is not listed falls back to a two-digit
216	     * country code, the most common E.164 length.
217	     */
218	    String[] KNOWN_CALLING_CODES = { "61", "1" };
219	
220	    /**
221	     * Format the owner's stored E.164 {@code telephone} for humans: the country code, a space, then
222	     * the national digits grouped in threes (e.g. {@code "+61412345678"} becomes
223	     * {@code "+61 412 345 678"}). Returns null when the owner or its telephone is absent, and returns
224	     * the value unchanged when it is not in E.164 form.
225	     */
226	    default String deriveTelephoneDisplay(Owner owner) {
227	        if (owner == null || owner.getTelephone() == null) {
228	            return null;
229	        }
230	        String telephone = owner.getTelephone();
231	        if (!telephone.startsWith("+")) {
232	            return telephone;
233	        }
234	        String digits = telephone.substring(1);
235	        int codeLength = 2;
236	        for (String code : KNOWN_CALLING_CODES) {
237	            if (digits.startsWith(code) && digits.length() > code.length()) {
238	                codeLength = code.length();
239	                break;
240	            }
241	        }
242	        if (digits.length() <= codeLength) {
243	            return telephone;
244	        }
245	        String national = digits.substring(codeLength);
246	        StringBuilder display = new StringBuilder("+").append(digits, 0, codeLength);
247	        for (int i = 0; i < national.length(); i += 3) {
248	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
249	        }
250	        return display.toString();
251	    }
252	
253	    /**
254	     * Derive the owner's salutation: the honorific {@code title} followed by a single space and the
255	     * {@code lastName} (e.g. {@code "DR Who"}). When the owner has no title (null or blank) the
256	     * salutation is just the {@code lastName}. Returns null when the owner is absent.
257	     */
258	    default String deriveSalutation(Owner owner) {
259	        if (owner == null) {
260	            return null;
261	        }
262	        String title = owner.getTitle();
263	        String lastName = owner.getLastName();
264	        if (title == null || title.isBlank()) {
265	            return lastName;
266	        }
267	        return title + " " + lastName;
268	    }
269	
270	    /**
271	     * Derive the owner's fiscal year from its business-day-adjusted {@code registrationDate},
272	     * formatted {@code 'FY<YY>'} where YY is the last two digits of the fiscal year. The fiscal
273	     * year starts on 1 July and is labelled by the calendar year in which it ends, so a
274	     * registrationDate on or after 1 July belongs to the fiscal year ending the following calendar
275	     * year. Returns null when the owner or its registrationDate is absent.
276	     */
277	    default String deriveFiscalYear(Owner owner) {
278	        if (owner == null || owner.getRegistrationDate() == null) {
279	            return null;
280	        }
281	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
282	        int fiscalYear = registrationDate.getMonthValue() >= java.time.Month.JULY.getValue()
283	            ? registrationDate.getYear() + 1 : registrationDate.getYear();
284	        return String.format("FY%02d", fiscalYear % 100);
285	    }
286	
287	    /**
288	     * Derive the owner's {@code identityKey}: the 64-character lower-case SHA-256 hex digest over
289	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. The telephone and
290	     * email are the owner's already-normalized stored values (E.164 telephone, lower-cased email); a
291	     * null email contributes an empty middle segment. Returns null when the owner is absent. This is
292	     * the same key duplicate detection compares on create.
293	     */
294	    default String deriveIdentityKey(Owner owner) {
295	        if (owner == null) {
296	            return null;
297	        }
298	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
299	        String email = owner.getEmail() == null ? "" : owner.getEmail();
300	        return sha256Hex(telephone + "|" + email + "|" + soundex(owner.getLastName()));
301	    }
302	
303	    /**
304	     * The American Soundex code of a name: its first letter followed by up to three digits encoding
305	     * the remaining consonants (b/f/p/v->1, c/g/j/k/q/s/x/z->2, d/t->3, l->4, m/n->5, r->6), with
306	     * adjacent duplicate codes collapsed, vowels (and y) resetting the run, and h/w transparent. The
307	     * result is padded with zeros to exactly four characters. A null or letterless name yields "".
308	     */
309	    private static String soundex(String name) {
310	        if (name == null) {
311	            return "";
312	        }
313	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
314	        if (letters.isEmpty()) {
315	            return "";
316	        }
317	        StringBuilder code = new StringBuilder();
318	        code.append(letters.charAt(0));
319	        char prev = soundexCode(letters.charAt(0));
320	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
321	            char c = letters.charAt(i);
322	            if (c == 'H' || c == 'W') {
323	                continue;
324	            }
325	            char digit = soundexCode(c);
326	            if (digit != '0' && digit != prev) {
327	                code.append(digit);
328	            }
329	            prev = digit;
330	        }
331	        while (code.length() < 4) {
332	            code.append('0');
333	        }
334	        return code.toString();
335	    }
336	
337	    /**
338	     * The Soundex digit for a single upper-case letter, or {@code '0'} for a vowel, y, h or w.
339	     */
340	    private static char soundexCode(char c) {
341	        return switch (c) {
342	            case 'B', 'F', 'P', 'V' -> '1';
343	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
344	            case 'D', 'T' -> '3';
345	            case 'L' -> '4';
346	            case 'M', 'N' -> '5';
347	            case 'R' -> '6';
348	            default -> '0';
349	        };
350	    }
351	
352	    /**
353	     * The full lower-case SHA-256 hex digest (64 characters) of the UTF-8 bytes of {@code value}.
354	     */
355	    private static String sha256Hex(String value) {
356	        try {
357	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
358	            StringBuilder sb = new StringBuilder(digest.length * 2);
359	            for (byte b : digest) {
360	                sb.append(String.format("%02x", b));
361	            }
362	            return sb.toString();
363	        }
364	        catch (NoSuchAlgorithmException ex) {
365	            throw new IllegalStateException("SHA-256 not available", ex);
366	        }
367	    }
368	
369	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
370	        OwnerPageDto ownerPageDto = new OwnerPageDto();
371	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
372	        ownerPageDto.setPage(ownerPage.getNumber());
373	        ownerPageDto.setSize(ownerPage.getSize());
374	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
375	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
376	        return ownerPageDto;
377	    }
378	}
